mdlSource:
create or modify page Tasks.Task_Overview (Title: 'Tasks', Layout: Atlas_Core.Atlas_Default) {
  datagrid dgTasks (DataSource: database from Tasks.Task, Selection: Single) {
    -- Context: $currentObject (Tasks.Task), $dgTasks (selection)
    controlbar {
      actionbutton btnNew (
        Caption: 'New task',
        Action: create object Tasks.Task then show page Tasks.Task_NewEdit,
        ButtonStyle: Primary
      )
      actionbutton btnEdit (Caption: 'Edit', Action: show page Tasks.Task_NewEdit(Task = $dgTasks))
    }
    column (Attribute: Title, Caption: 'Title')
    column (Attribute: Done, Caption: 'Done')
  }
};

grant view on page Tasks.Task_Overview to Tasks.User;
